package com.ittefaq.analytics

import android.app.*
import android.os.*
import android.content.*
import android.database.sqlite.*
import android.graphics.*
import android.graphics.pdf.PdfDocument
import android.view.*
import android.widget.*
import java.io.File
import java.text.NumberFormat
import java.time.*
import java.time.format.DateTimeFormatter
import java.util.Locale

class Store(ctx: Context): SQLiteOpenHelper(ctx,"ittefaq.db",null,1) {
 override fun onCreate(db:SQLiteDatabase){
  db.execSQL("CREATE TABLE departments(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL)")
  db.execSQL("CREATE TABLE monthly(month TEXT PRIMARY KEY,sales REAL NOT NULL DEFAULT 0,profit REAL NOT NULL DEFAULT 0,liability REAL NOT NULL DEFAULT 0)")
  db.execSQL("CREATE TABLE stock(month TEXT NOT NULL,department_id INTEGER NOT NULL,amount REAL NOT NULL DEFAULT 0,PRIMARY KEY(month,department_id))")
  listOf("Season","Reshmi","Pret Ladies","Gents","Stitched Gents","Hajj & Umrah","Perfumes","Watches").forEach { db.execSQL("INSERT INTO departments(name) VALUES(?)", arrayOf(it)) }
 }
 override fun onUpgrade(db:SQLiteDatabase,oldVersion:Int,newVersion:Int){}
 fun departments():List<Pair<Int,String>> { val a= mutableListOf<Pair<Int,String>>(); readableDatabase.rawQuery("SELECT id,name FROM departments ORDER BY id",null).use { while(it.moveToNext()) a.add(it.getInt(0) to it.getString(1)) };return a }
 fun addDepartment(name:String){writableDatabase.execSQL("INSERT INTO departments(name) VALUES(?)",arrayOf(name))}
 fun save(month:String,sales:Double,profit:Double,liability:Double,stocks:Map<Int,Double>){val db=writableDatabase;db.beginTransaction();try{db.execSQL("INSERT OR REPLACE INTO monthly(month,sales,profit,liability) VALUES(?,?,?,?)",arrayOf(month,sales,profit,liability));stocks.forEach{(id,value)->db.execSQL("INSERT OR REPLACE INTO stock(month,department_id,amount) VALUES(?,?,?)",arrayOf(month,id,value))};db.setTransactionSuccessful()}finally{db.endTransaction()}}
 fun month(key:String):Triple<Double,Double,Double>{readableDatabase.rawQuery("SELECT sales,profit,liability FROM monthly WHERE month=?",arrayOf(key)).use { if(it.moveToFirst())return Triple(it.getDouble(0),it.getDouble(1),it.getDouble(2)) };return Triple(0.0,0.0,0.0)}
 fun stocks(key:String):Map<Int,Double>{val m= mutableMapOf<Int,Double>();readableDatabase.rawQuery("SELECT department_id,amount FROM stock WHERE month=?",arrayOf(key)).use {while(it.moveToNext())m[it.getInt(0)]=it.getDouble(1)};return m}
 fun months():List<String>{val a= mutableListOf<String>();readableDatabase.rawQuery("SELECT month FROM monthly ORDER BY month DESC",null).use{while(it.moveToNext())a.add(it.getString(0))};return a}
}

class MainActivity:Activity(){
 private lateinit var db:Store;private lateinit var root:LinearLayout;private var selected=YearMonth.now();private val money=NumberFormat.getNumberInstance(Locale("en","PK"));private val ink=Color.rgb(21,42,56)
 private fun fmt(n:Double)="Rs ${money.format(n)}"
 private fun label(s:String,size:Float=16f):TextView=TextView(this).apply{text=s;textSize=size;setTextColor(ink);setPadding(8,10,8,10)}
 private fun field(hint:String,value:String=""):EditText=EditText(this).apply{setSingleLine(true);this.hint=hint;setText(value);inputType=android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL;setPadding(12,8,12,8)}
 private fun btn(text:String,run:()->Unit){root.addView(Button(this).apply{this.text=text;setOnClickListener{run()}})}
 private fun section(title:String){root.addView(label(title,21f))}
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);db=Store(this);showHome()}
 private fun screen(title:String){val sc=ScrollView(this);root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(20,20,20,28);setBackgroundColor(Color.rgb(247,249,251))};sc.addView(root);setContentView(sc);root.addView(label("ITTEFAQ CLOTH HOUSE",25f));root.addView(label(title,18f))}
 private fun delta(now:Double,prev:Double):String {val d=now-prev;val pct=if(prev==0.0)"N/A" else "%.1f%%".format(Locale.US,d/prev*100);return "${if(d>=0)"▲" else "▼"} ${fmt(kotlin.math.abs(d))} ($pct)"}
 private fun previous()=selected.minusMonths(1).toString()
 private fun summary(key:String):String{val (s,p,l)=db.month(key);val stocks=db.stocks(key);val total=stocks.values.sum();val days=YearMonth.parse(key).lengthOfMonth();val cost=s-p;val roi=if(cost>0) p/cost*100 else 0.0;val margin=if(s>0)p/s*100 else 0.0
  val tiers=listOf(100000.0 to "Brown",150000.0 to "Silver",250000.0 to "Golden",300000.0 to "Super Golden",350000.0 to "Platinum",400000.0 to "Royal",500000.0 to "Super Royal")
  val star=tiers.lastOrNull{ s>=it.first }?.second?:"Below Brown"
  return "Month: $key\nSales: ${fmt(s)}\nProfit: ${fmt(p)}\nEstimated cost (Sales − Profit): ${fmt(cost)}\nProfit margin: %.2f%%\nEstimated ROI on cost: %.2f%%\nAverage daily sales: ${fmt(s/days)}\nAverage daily profit: ${fmt(p/days)}\nSales Star: $star\nTotal stock: ${fmt(total)}\nMarket liability: ${fmt(l)}\nNet stock position: ${fmt(total-l)}".format(Locale.US,margin,roi)
 }
 private fun showHome(){screen("Business dashboard");btn("Cloud account & sync"){cloudScreen()};val key=selected.toString();root.addView(label("Selected: $key",20f));btn("◀ Previous month"){selected=selected.minusMonths(1);showHome()};btn("Next month ▶"){selected=selected.plusMonths(1);showHome()};root.addView(label(summary(key)));section("Monthly comparison");val (s,p,l)=db.month(key);val (ps,pp,pl)=db.month(previous());val currentStock=db.stocks(key).values.sum();val oldStock=db.stocks(previous()).values.sum();listOf("Sales" to delta(s,ps),"Profit" to delta(p,pp),"Liabilities" to delta(l,pl),"Stock" to delta(currentStock,oldStock)).forEach{root.addView(label("${it.first}: ${it.second}"))};section("Same month last year");val (ys,yp,yl)=db.month(selected.minusYears(1).toString());root.addView(label("Sales: ${delta(s,ys)}\nProfit: ${delta(p,yp)}\nLiability: ${delta(l,yl)}"));section("Department stock");val now=db.stocks(key);val old=db.stocks(previous());db.departments().forEach{(id,name)->root.addView(label("$name: ${fmt(now[id]?:0.0)} | ${delta(now[id]?:0.0,old[id]?:0.0)}"))};root.addView(TrendView(this,db.months().reversed().takeLast(12).map{it to db.month(it).first}));btn("Enter / edit monthly audit"){edit()};btn("Monthly & yearly history"){history()};btn("Add department"){addDepartment()};btn("Set monthly audit reminder"){reminder()};btn("Export this month as PDF"){exportPdf(key)} }
 private fun cloudScreen(){screen("Cloud database");root.addView(label("Use the same business ID on every authorized phone. Sign in, then choose Upload or Download. Download replaces this phone’s local records. Do not edit on two phones before syncing."));val email=EditText(this).apply{hint="Email";inputType=33};val password=EditText(this).apply{hint="Password";inputType=129};val business=EditText(this).apply{hint="Business UUID";setText(getPreferences(0).getString("business_id", ""))};root.addView(email);root.addView(password);root.addView(business);val api=CloudApi(this);fun runTask(message:String,block:()->String){root.addView(label(message));Thread{val result=try{block()}catch(e:Exception){"Error: ${e.message}"};runOnUiThread{AlertDialog.Builder(this).setMessage(result).setPositiveButton("OK",null).show()}}.start()};btn("Sign in"){runTask("Signing in..."){api.signIn(email.text.toString().trim(),password.text.toString())}};btn("Save business ID"){getPreferences(0).edit().putString("business_id",business.text.toString().trim()).apply();Toast.makeText(this,"Business ID saved",Toast.LENGTH_SHORT).show()};btn("Upload local records to cloud"){AlertDialog.Builder(this).setTitle("Upload records?").setMessage("Uploads all saved months. Cloud records for matching months will be replaced. First download if other phones have newer records.").setPositiveButton("Upload"){_,_->runTask("Uploading..."){api.upload(db,business.text.toString().trim())}}.setNegativeButton("Cancel",null).show()};btn("Download cloud records to this phone"){AlertDialog.Builder(this).setTitle("Download records?").setMessage("Cloud records will replace matching months and stock values on this phone. Back up important local data first.").setPositiveButton("Download"){_,_->runTask("Downloading..."){api.download(db,business.text.toString().trim())}}.setNegativeButton("Cancel",null).show()};btn("Back"){showHome()}}
 private fun edit(){screen("Enter audit for ${selected}");val old=db.month(selected.toString());root.addView(label("Enter amounts in PKR"));val sales=field("Sales",old.first.toString());root.addView(label("Monthly sales"));root.addView(sales);val profit=field("Profit",old.second.toString());root.addView(label("Monthly profit"));root.addView(profit);val liability=field("Liability",old.third.toString());root.addView(label("Market liability"));root.addView(liability);section("Department stock worth");val oldStocks=db.stocks(selected.toString());val fields=db.departments().associate{(id,name)->root.addView(label(name));val f=field(name,(oldStocks[id]?:0.0).toString());root.addView(f);id to f};btn("Save monthly record"){try{val s=sales.text.toString().toDouble();val p=profit.text.toString().toDouble();val l=liability.text.toString().toDouble();val st=fields.mapValues{it.value.text.toString().toDouble()};require(s>=0&&p>=0&&l>=0&&st.values.all{it>=0}){"Amounts cannot be negative"};require(p<=s){"Profit cannot exceed sales"};db.save(selected.toString(),s,p,l,st);Toast.makeText(this,"Record saved",Toast.LENGTH_SHORT).show();showHome()}catch(e:Exception){Toast.makeText(this,e.message?:"Invalid amount",Toast.LENGTH_LONG).show()}};btn("Back"){showHome()} }
 private fun addDepartment(){val f=EditText(this);AlertDialog.Builder(this).setTitle("New department").setView(f).setPositiveButton("Add"){_,_->try{val name=f.text.toString().trim();require(name.isNotEmpty());db.addDepartment(name);showHome()}catch(e:Exception){Toast.makeText(this,"Department already exists or name is empty",Toast.LENGTH_LONG).show()}}.setNegativeButton("Cancel",null).show()}
 private fun history(){screen("History");val months=db.months();if(months.isEmpty())root.addView(label("No records saved yet"));months.groupBy{it.substring(0,4)}.forEach{(year,records)->section(year);val totalSales=records.sumOf{db.month(it).first};val totalProfit=records.sumOf{db.month(it).second};root.addView(label("Year sales: ${fmt(totalSales)} | Year profit: ${fmt(totalProfit)}"));records.forEach{key->btn("$key — ${fmt(db.month(key).first)}"){selected=YearMonth.parse(key);showHome()}}};btn("Back"){showHome()}}
 private fun reminder(){val edit=EditText(this).apply{inputType=2;setText(getPreferences(0).getInt("audit_day",1).toString())};AlertDialog.Builder(this).setTitle("Monthly audit day (1–28)").setView(edit).setPositiveButton("Save"){_,_->val day=edit.text.toString().toIntOrNull();if(day==null||day !in 1..28){Toast.makeText(this,"Choose 1–28",Toast.LENGTH_LONG).show()}else{getPreferences(0).edit().putInt("audit_day",day).apply();schedule(day);Toast.makeText(this,"Monthly reminder scheduled",Toast.LENGTH_LONG).show()}}.setNegativeButton("Cancel",null).show()}
 private fun schedule(day:Int){val manager=getSystemService(ALARM_SERVICE) as AlarmManager;val intent=PendingIntent.getBroadcast(this,100,Intent(this,AuditReceiver::class.java),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);var date=LocalDate.now().withDayOfMonth(day);if(!date.isAfter(LocalDate.now()))date=date.plusMonths(1);val at=date.atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();manager.setInexactRepeating(AlarmManager.RTC_WAKEUP,at,AlarmManager.INTERVAL_DAY*30,intent);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(arrayOf(android.Manifest.permission.POST_NOTIFICATIONS),2)}
 private fun exportPdf(key:String){try{val pdf=PdfDocument();val page=pdf.startPage(PdfDocument.PageInfo.Builder(595,842,1).create());val c=page.canvas;val paint=Paint(3).apply{color=ink;textSize=17f};c.drawText("ITTEFAQ CLOTH HOUSE",35f,48f,paint);paint.textSize=12f;var y=80f;summary(key).lines().forEach{c.drawText(it,35f,y,paint);y+=22};y+=12;c.drawText("Department stock:",35f,y,paint);y+=22;db.departments().forEach{(id,name)->c.drawText("$name: ${fmt(db.stocks(key)[id]?:0.0)}",35f,y,paint);y+=20};pdf.finishPage(page);val dir=getExternalFilesDir(android.os.Environment.DIRECTORY_DOCUMENTS)?:filesDir;val file=File(dir,"Ittefaq_Report_$key.pdf");file.outputStream().use{pdf.writeTo(it)};pdf.close();AlertDialog.Builder(this).setMessage("PDF saved to:\n${file.absolutePath}\n\nYou can access it using a file manager.").setPositiveButton("OK",null).show()}catch(e:Exception){Toast.makeText(this,"PDF error: ${e.message}",Toast.LENGTH_LONG).show()}}
}
class TrendView(ctx:Context,private val data:List<Pair<String,Double>>):View(ctx){private val p=Paint(3);override fun onMeasure(w:Int,h:Int){setMeasuredDimension(MeasureSpec.getSize(w),250)};override fun onDraw(c:Canvas){super.onDraw(c);if(data.isEmpty())return;val left=45f;val top=20f;val bottom=height-35f;val right=width-15f;val max=data.maxOf{it.second}.coerceAtLeast(1.0);p.color=Color.rgb(24,126,141);p.strokeWidth=5f;p.style=Paint.Style.STROKE;val path=Path();data.forEachIndexed{i,item->val x=if(data.size==1)(left+right)/2 else left+(right-left)*i/(data.size-1);val y=bottom-((bottom-top)*item.second/max).toFloat();if(i==0)path.moveTo(x,y)else path.lineTo(x,y)};c.drawPath(path,p);p.style=Paint.Style.FILL;p.textSize=23f;p.color=Color.DKGRAY;c.drawText("Sales trend (last 12 saved months)",15f,height-8f,p)}}
class AuditReceiver:android.content.BroadcastReceiver(){override fun onReceive(context:Context,intent:Intent){val manager=context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;val channel="audits";if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(NotificationChannel(channel,"Stock audit reminders",NotificationManager.IMPORTANCE_DEFAULT));val n=Notification.Builder(context,channel).setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("ITTEFAQ CLOTH HOUSE").setContentText("Today is your monthly stock, sales and liability audit day.").setAutoCancel(true).build();manager.notify(100,n)}}
